package ir.daftarsetareh.offline;

import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/** Validated creation and editing dialogs. Saving never dismisses an invalid form. */
final class Forms {
    final MainActivity a; final Ui ui; final Store db;
    Forms(MainActivity activity){a=activity;ui=a.ui;db=a.store;}
    static List<Ui.Choice> options(String... values){List<Ui.Choice> result=new ArrayList<>();for(String value:values)result.add(new Ui.Choice(value,value));return result;}
    List<Ui.Choice> subjects(boolean optional,String selected){List<Ui.Choice> result=new ArrayList<>();if(optional)result.add(new Ui.Choice("","بدون درس"));for(JSONObject subject:db.all("subjects"))if(!subject.optBoolean("archived")||subject.optString("id").equals(selected))result.add(new Ui.Choice(subject.optString("id"),subject.optString("name")+(subject.optBoolean("archived")?" (بایگانی)":"")));return result;}
    String str(JSONObject value,String field,String fallback){return value==null?fallback:value.optString(field,fallback);}
    String recordId(JSONObject value){return value==null?Store.id():value.optString("id");}
    void subject(JSONObject existing){Ui.Form form=ui.new Form();EditText name=form.field("نام درس",str(existing,"name",""),false,false);List<Ui.Choice> colors=Arrays.asList(new Ui.Choice("#6C5CE7","بنفش"),new Ui.Choice("#13B5A6","فیروزه‌ای"),new Ui.Choice("#F06E86","صورتی"),new Ui.Choice("#2E9BEA","آبی"),new Ui.Choice("#D9A21B","طلایی"),new Ui.Choice("#3DBE72","سبز"));Spinner color=form.choice("رنگ درس",colors,str(existing,"color","#6C5CE7"));form.note("درس‌های استفاده‌شده بایگانی می‌شوند تا سوابق گزارش و نمره از بین نرود.");form.show(existing==null?"درس تازه":"ویرایش درس",()->db.save("subjects",Store.object("id",recordId(existing),"name",Ui.value(name),"color",Ui.selected(color),"archived",existing!=null&&existing.optBoolean("archived"))));}
    void profile(){JSONObject current=db.profile();Ui.Form form=ui.new Form();EditText name=form.field("نام",current.optString("name"),false,false),grade=form.field("پایه (۱ تا ۱۲)",current.optString("grade"),true,false),field=form.field("رشته / گروه",current.optString("field"),false,false),scale=form.field("مقیاس نمایش نمره (مثلاً ۲۰)",current.optString("scale"),true,false),goal=form.field("هدف روزانه، دقیقه",current.optString("dailyGoal"),true,false);form.note("تغییر مقیاس، نمرهٔ خام آزمون‌ها را تغییر نمی‌دهد؛ فقط نمایش میانگین را تبدیل می‌کند.");form.show("پروفایل من",()->db.save("profile",Store.object("id","local","name",Ui.value(name),"grade",whole(grade,1,12,"پایه"),"field",Ui.value(field),"scale",Core.number(Ui.value(scale),1,100,"مقیاس"),"dailyGoal",whole(goal,5,1440,"هدف روزانه"),"demo",current.optBoolean("demo"))));}
    static int whole(EditText input,int min,int max,String label){double value=Core.number(Ui.value(input),min,max,label);Store.require(value==Math.floor(value),label+" باید عدد صحیح باشد.");return (int)value;}
    void report(JSONObject existing){
        Ui.Form form=ui.new Form();Button date=form.date("تاریخ گزارش",str(existing,"date",Dates.today()));form.note("فقط درس‌هایی را پر کن که مطالعه کردی. بقیه می‌توانند خالی بمانند.");
        LinkedHashMap<String,EditText> minuteInputs=new LinkedHashMap<>();JSONArray oldRows=existing==null?new JSONArray():existing.optJSONArray("subjects");
        for(JSONObject subject:db.all("subjects")){String id=subject.optString("id");int minutes=0;for(int i=0;i<oldRows.length();i++)if(oldRows.optJSONObject(i).optString("subjectId").equals(id))minutes=oldRows.optJSONObject(i).optInt("minutes");if(subject.optBoolean("archived")&&minutes==0)continue;minuteInputs.put(id,form.field(subject.optString("name")+" • دقیقه",minutes==0?"":String.valueOf(minutes),true,false));}
        if(minuteInputs.isEmpty())form.note("برای ثبت زمان، ابتدا از بخش درس‌ها یک درس اضافه کن.");
        StringBuilder taskLines=new StringBuilder();JSONArray oldTasks=existing==null?new JSONArray():existing.optJSONArray("tasks");for(int i=0;i<oldTasks.length();i++){JSONObject task=oldTasks.optJSONObject(i);taskLines.append(task.optString("title")).append('\n');}
        form.section("کارها و یادداشت‌ها (اختیاری)",false);
        EditText tasks=form.field("کارها؛ هر خط یک کار",taskLines.toString().trim(),false,true);form.note("هر خط یک کار. بعد از ذخیره، کار انجام‌شده را از فهرست مطالعه تیک بزن.");
        EditText lessons=form.field("چه درس‌هایی را مرور کردی؟",str(existing,"lessons",""),false,true),exercises=form.field("تمرین‌ها و فعالیت‌ها",str(existing,"exercises",""),false,true),difficulties=form.field("چه چیزی دشوار بود؟",str(existing,"difficulties",""),false,true),reflection=form.field("یادداشت و حس امروز",str(existing,"reflection",""),false,true),next=form.field("قدم بعدی و هدف فردا",str(existing,"nextGoals",""),false,true);
        form.endSection();
        form.show(existing==null?"ثبت مطالعه":"ویرایش مطالعه",()->{
            JSONArray rows=new JSONArray();for(Map.Entry<String,EditText> item:minuteInputs.entrySet())if(!Ui.value(item.getValue()).isEmpty()){int minutes=whole(item.getValue(),0,1440,"دقیقه");String note="";for(int i=0;i<oldRows.length();i++)if(oldRows.optJSONObject(i).optString("subjectId").equals(item.getKey()))note=oldRows.optJSONObject(i).optString("note");if(minutes>0)rows.put(Store.object("subjectId",item.getKey(),"minutes",minutes,"note",note));}
            Map<String,Deque<JSONObject>> associations=new HashMap<>();for(int i=0;i<oldTasks.length();i++){JSONObject task=oldTasks.optJSONObject(i);associations.computeIfAbsent(task.optString("title").trim(),key->new ArrayDeque<>()).add(task);}
            JSONArray taskRows=new JSONArray();for(String source:Ui.value(tasks).split("\\r?\n")){String line=source.trim();if(line.isEmpty())continue;boolean done=line.matches("(?i)^(?:\\[x\\]|✓|✔).*" );String title=line.replaceFirst("(?i)^(?:\\[[x ]?\\]|✓|✔)\\s*","").trim();Deque<JSONObject> previous=associations.get(title);JSONObject prior=previous==null||previous.isEmpty()?null:previous.removeFirst();String subjectId=prior==null?"":prior.optString("subjectId");boolean explicit=line.matches("(?i)^(?:\\[[x ]?\\]|✓|✔).*" );if(!explicit&&prior!=null)done=prior.optBoolean("completed");taskRows.put(Store.object("title",title,"completed",done,"subjectId",subjectId));}
            db.save("reports",Store.object("id",recordId(existing),"date",date.getTag(),"subjects",rows,"tasks",taskRows,"lessons",Ui.value(lessons),"exercises",Ui.value(exercises),"difficulties",Ui.value(difficulties),"reflection",Ui.value(reflection),"nextGoals",Ui.value(next)));
        });
    }
    void exam(JSONObject existing){
        List<Ui.Choice> subjects=subjects(false,str(existing,"subjectId",""));if(subjects.isEmpty()){ui.toast("اول یک درس اضافه کن.");a.navigate("subjects");return;}
        Ui.Form form=ui.new Form();Spinner subject=form.choice("درس",subjects,str(existing,"subjectId",""));EditText title=form.field("عنوان آزمون",str(existing,"title",""),false,false);Button date=form.date("تاریخ آزمون",str(existing,"date",Dates.today()));
        EditText grade=form.field("نمرهٔ کسب‌شده (خالی = هنوز اعلام نشده)",existing==null||existing.isNull("grade")?"":existing.optString("grade"),true,false),max=form.field("نمرهٔ کل آزمون",str(existing,"maxGrade",db.profile().optString("scale","20")),true,false);form.section("ضریب و یادداشت (اختیاری)",false);EditText weight=form.field("ضریب (اختیاری، ۰٫۱ تا ۱۰)",existing==null||existing.isNull("weight")?"":existing.optString("weight"),true,false),notes=form.field("یادداشت",str(existing,"notes",""),false,true);
        form.note("نمرهٔ خالی یعنی هنوز اعلام نشده؛ صفر یک نمرهٔ واقعی است.");form.endSection();
        form.show(existing==null?"آزمون تازه":"ویرایش آزمون",()->{double maximum=Core.number(Ui.value(max),1,10000,"نمرهٔ کل");db.save("exams",Store.object("id",recordId(existing),"subjectId",Ui.selected(subject),"title",Ui.value(title),"date",date.getTag(),"grade",Ui.value(grade).isEmpty()?null:Core.number(Ui.value(grade),0,maximum,"نمره"),"maxGrade",maximum,"weight",Ui.value(weight).isEmpty()?null:Core.number(Ui.value(weight),.1,10,"ضریب"),"notes",Ui.value(notes)));});
    }
    void session(JSONObject existing){
        Ui.Form form=ui.new Form();Spinner subject=form.choice("درس (اختیاری)",subjects(true,str(existing,"subjectId","")),str(existing,"subjectId",""));EditText title=form.field("عنوان جلسه",str(existing,"title",""),false,false);Button date=form.date("روز جلسه / شروع تکرار",str(existing,"date",a.referenceDate));EditText time=form.field("ساعت شروع (۲۴ ساعته، مانند ۱۶:۳۰)",str(existing,"time","16:00"),false,false);time.setTextDirection(android.view.View.TEXT_DIRECTION_LTR);EditText duration=form.field("مدت، دقیقه",str(existing,"duration","45"),true,false);form.section("جزئیات و تکرار (اختیاری)",false);Spinner kind=form.choice("نوع جلسه",options("مطالعه","تکلیف","مرور","آزمون","پروژه"),str(existing,"kind","مطالعه")),priority=form.choice("اولویت",options("عادی","مهم","خیلی مهم"),str(existing,"priority","عادی"));EditText notes=form.field("یادداشت",str(existing,"notes",""),false,true);
        CheckBox repeat=form.check("تکرار این برنامه",false);android.widget.LinearLayout repetition=ui.column();ui.add(form.target,repetition);form.target=repetition;Button end=form.date("پایان تکرار (حداکثر ۱۲۰ روز)",LocalDate.parse((String)date.getTag()).plusDays(28).toString());List<CheckBox> days=new ArrayList<>();DayOfWeek[] order={DayOfWeek.SATURDAY,DayOfWeek.SUNDAY,DayOfWeek.MONDAY,DayOfWeek.TUESDAY,DayOfWeek.WEDNESDAY,DayOfWeek.THURSDAY,DayOfWeek.FRIDAY};String[] labels={"شنبه","یکشنبه","دوشنبه","سه‌شنبه","چهارشنبه","پنجشنبه","جمعه"};for(int i=0;i<7;i++)days.add(form.check(labels[i],order[i]==LocalDate.parse((String)date.getTag()).getDayOfWeek()));
        repetition.setVisibility(android.view.View.GONE);repeat.setOnCheckedChangeListener((button,checked)->repetition.setVisibility(checked?android.view.View.VISIBLE:android.view.View.GONE));form.endSection();
        if(existing!=null){repeat.setEnabled(false);form.note("ویرایش فقط همین جلسه را تغییر می‌دهد. حذف مجموعه از کارت جلسه در دسترس است.");}else form.note("اگر تکرار خاموش باشد فقط روز شروع ذخیره می‌شود. تکرارها مستقل تکمیل می‌شوند.");
        form.show(existing==null?"افزودن برنامه":"ویرایش جلسه",()->{String start=(String)date.getTag(),last=repeat.isChecked()?(String)end.getTag():start;int minutes=whole(duration,5,600,"مدت");String startTime=Core.ascii(Ui.value(time));Core.validateSession(startTime,minutes);Set<DayOfWeek> weekdays=new HashSet<>();for(int i=0;i<7;i++)if(days.get(i).isChecked())weekdays.add(order[i]);List<String> dates=Core.recurrence(start,last,weekdays,repeat.isChecked());String series=existing!=null?existing.optString("seriesId"):repeat.isChecked()?Store.id():"";List<JSONObject> sessions=new ArrayList<>();for(String day:dates)sessions.add(Store.object("id",recordId(existing),"subjectId",Ui.selected(subject),"title",Ui.value(title),"date",day,"time",startTime,"duration",minutes,"completed",existing!=null&&existing.optBoolean("completed"),"seriesId",series,"kind",Ui.selected(kind),"priority",Ui.selected(priority),"notes",Ui.value(notes)));db.saveSessions(sessions);a.referenceDate=start;});
    }
    void goal(JSONObject existing){
        Ui.Form form=ui.new Form();EditText title=form.field("عنوان هدف",str(existing,"title",""),false,false);List<Ui.Choice> metrics=Arrays.asList(new Ui.Choice("minutes","دقیقهٔ مطالعه"),new Ui.Choice("tasks","تعداد کار انجام‌شده"),new Ui.Choice("average","میانگین نمره به درصد"));Spinner metric=form.choice("معیار",metrics,str(existing,"metric","minutes"));List<Ui.Choice> periods=Arrays.asList(new Ui.Choice("daily","روزانه"),new Ui.Choice("weekly","هفتگی"),new Ui.Choice("monthly","ماهانه"));Spinner period=form.choice("دورهٔ ارزیابی",periods,str(existing,"period","weekly"));EditText target=form.field("مقدار هدف",str(existing,"target","300"),true,false);Button start=form.date("شروع اعتبار",str(existing,"start",Dates.today())),end=form.date("پایان اعتبار",str(existing,"end",LocalDate.parse(Dates.today()).plusDays(90).toString()));CheckBox active=form.check("هدف فعال باشد",existing==null||existing.optBoolean("active"));form.note("پیشرفت فقط از اشتراک دورهٔ جاری با بازهٔ اعتبار هدف محاسبه می‌شود. هدف خارج از بازه، پیشرفت صفر دارد.");form.show(existing==null?"هدف تازه":"ویرایش هدف",()->db.save("goals",Store.object("id",recordId(existing),"title",Ui.value(title),"metric",Ui.selected(metric),"period",Ui.selected(period),"target",Core.number(Ui.value(target),1,Ui.selected(metric).equals("average")?100:100000,"مقدار هدف"),"start",start.getTag(),"end",end.getTag(),"active",active.isChecked())));
    }
}
